style:
/* 旗墨 —— 顶部 RESUME 旗标，藏青标牌标题压在细线上 */

.tw-qimo.layout-band.resume-paper .paper-flow::before {
  content: "RESUME";
  display: block;
  width: 36mm;
  margin: 0 auto 7mm;
  padding: 1.6mm 0;
  background: var(--paper-accent);
  clip-path: polygon(3.4mm 0, 100% 0, calc(100% - 3.4mm) 100%, 0 100%);
  color: #fff;
  font-size: calc(var(--paper-base-size) * 1.14);
  font-weight: 700;
  letter-spacing: 0.34em;
  text-align: center;
  text-indent: 0.34em;
  print-color-adjust: exact;
}

.tw-qimo.layout-band.resume-paper .paper-header {
  margin-bottom: 6.5mm;
  padding-bottom: 4.4mm;
  border-bottom: 0.3mm solid #d8dfe8;
}

.tw-qimo.layout-band.resume-paper .paper-header--photo {
  align-items: flex-start;
  gap: 8mm;
}

.tw-qimo.layout-band.resume-paper .paper-header__main {
  flex: 1 1 auto;
  min-width: 0;
}

.tw-qimo.layout-band.resume-paper .paper-photo {
  order: 3;
  width: 24mm;
  height: 33mm;
  border: 0.4mm solid #dde3ea;
  border-radius: 0;
  box-shadow: none;
}

.tw-qimo.layout-band.resume-paper .paper-photo--monogram {
  display: grid;
  place-items: center;
  background: #eef1f6;
  color: var(--paper-accent);
  font-size: calc(var(--paper-base-size) * 2);
  font-weight: 700;
}

.tw-qimo.layout-band.resume-paper .paper-name {
  color: #182430;
  font-family: var(--paper-font-family);
  font-size: calc(var(--paper-base-size) * 2.3);
  letter-spacing: 0.08em;
}

.tw-qimo.layout-band.resume-paper .paper-identity {
  padding: 0;
  border: none;
  color: #66757f;
  font-size: calc(var(--paper-base-size) * 0.84);
}

.tw-qimo.layout-band.resume-paper .paper-role {
  margin-top: 1.8mm;
  color: #33424f;
  font-size: calc(var(--paper-base-size) * 0.96);
  font-weight: 400;
}

.tw-qimo.layout-band.resume-paper .paper-contacts {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1.4mm 8mm;
  margin-top: 3.2mm;
  color: #33424f;
  font-size: calc(var(--paper-base-size) * 0.87);
}

.tw-qimo.layout-band.resume-paper .paper-contact {
  display: flex;
  gap: 1.8mm;
}

.tw-qimo.layout-band.resume-paper .paper-contact + .paper-contact::before {
  display: none;
}

.tw-qimo.layout-band.resume-paper .paper-contact__label {
  flex: 0 0 auto;
  color: #7a8894;
}

/* 标题：旗标贴齐正文左缘，后面拖一条细线 */
.tw-qimo.layout-band.resume-paper .paper-style-flag .paper-section__title {
  margin-left: 0;
  margin-bottom: 4mm;
}

.tw-qimo.layout-band.resume-paper .paper-section__body {
  color: #2f3d49;
}

.tw-qimo.layout-band.resume-paper .paper-item-title {
  color: #17222d;
}

.tw-qimo.layout-band.resume-paper .paper-item-period {
  color: #77848f;
  font-size: calc(var(--paper-base-size) * 0.86);
}

.tw-qimo.layout-band.resume-paper .paper-item-sub {
  color: #44525f;
}

.tw-qimo.layout-band.resume-paper .paper-rich ul,
.tw-qimo.layout-band.resume-paper .paper-rich ol {
  margin-top: 0.8mm;
  padding-left: 0;
  list-style: none;
}

.tw-qimo.layout-band.resume-paper .paper-rich li {
  position: relative;
  margin: 0.7mm 0;
  padding-left: 3.6mm;
}

.tw-qimo.layout-band.resume-paper .paper-rich li::before {
  content: "";
  position: absolute;
  top: 0.7em;
  left: 0.4mm;
  width: 1.1mm;
  height: 1.1mm;
  border-radius: 50%;
  background: var(--list-color, var(--paper-accent));
  print-color-adjust: exact;
}

.tw-qimo.layout-band.resume-paper .paper-note__tag {
  color: #17222d;
  font-weight: 600;
}

.tw-qimo.layout-band.resume-paper .paper-footer {
  border-top: 0.2mm solid #e2e7ee;
  color: #9ba7b3;
}

/* 显式选择的列表样式接管模板默认圆点装饰，避免 data-list 被模板 ul/li 规则盖掉。 */
.tw-qimo.resume-paper .paper-rich ul[data-list],
.tw-qimo.resume-paper .paper-rich ol[data-list] {
  margin: 0.5mm 0 0;
  padding-left: 1.2em;
}
.tw-qimo.resume-paper .paper-rich ul[data-list] > li,
.tw-qimo.resume-paper .paper-rich ol[data-list] > li {
  padding-left: 0;
  position: relative;
}
.tw-qimo.resume-paper .paper-rich ul[data-list] > li::before,
.tw-qimo.resume-paper .paper-rich ol[data-list] > li::before {
  content: none;
  width: auto;
  height: auto;
  border-radius: 0;
  background: none;
  border: 0;
  box-shadow: none;
  left: auto;
  right: auto;
  top: auto;
  margin: 0;
  padding: 0;
}
.tw-qimo.resume-paper .paper-rich ul[data-list="disc"] { list-style-type: disc; }
.tw-qimo.resume-paper .paper-rich ul[data-list="circle"] { list-style-type: circle; }
.tw-qimo.resume-paper .paper-rich ul[data-list="square"] { list-style-type: square; }
.tw-qimo.resume-paper .paper-rich ul[data-list="square-open"] { list-style-type: "□   "; }
.tw-qimo.resume-paper .paper-rich ul[data-list="square-open"] > li::marker { font-size: 0.62em; }
.tw-qimo.resume-paper .paper-rich ul[data-list="diamond"] { list-style-type: "◆   "; }
.tw-qimo.resume-paper .paper-rich ul[data-list="diamond-open"] { list-style-type: "◇   "; }
.tw-qimo.resume-paper .paper-rich ul[data-list="diamond"] > li::marker,
.tw-qimo.resume-paper .paper-rich ul[data-list="diamond-open"] > li::marker { font-size: 0.62em; }
.tw-qimo.resume-paper .paper-rich ul[data-list="triangle"] { list-style-type: "▸   "; }
.tw-qimo.resume-paper .paper-rich ul[data-list="check"] { list-style-type: "✓   "; }
.tw-qimo.resume-paper .paper-rich ul[data-list="check"] > li::marker { font-size: 0.75em; }
.tw-qimo.resume-paper .paper-rich ol[data-list="decimal"] { list-style-type: decimal; }
.tw-qimo.resume-paper .paper-rich ol[data-list="cjk"] { list-style-type: miniwho-cjk; }
.tw-qimo.resume-paper .paper-rich ol[data-list="roman-upper"] { list-style-type: upper-roman; }
.tw-qimo.resume-paper .paper-rich ol[data-list="roman-lower"] { list-style-type: lower-roman; }
.tw-qimo.resume-paper .paper-rich ol[data-list="alpha-upper"] { list-style-type: upper-alpha; }
.tw-qimo.resume-paper .paper-rich ol[data-list="alpha-lower"] { list-style-type: lower-alpha; }
.tw-qimo.resume-paper .paper-rich ol[data-list="paren"] { padding-left: 1.2em; list-style: none; counter-reset: paren-item; }
.tw-qimo.resume-paper .paper-rich ol[data-list="paren"] > li { position: relative; counter-increment: paren-item; }
.tw-qimo.resume-paper .paper-rich ol[data-list="paren"] > li::before {
  content: "（" counter(paren-item) "）";
  position: absolute;
  right: calc(100% + 0.08em);
  top: 0;
  font-family: var(--mono);
  font-variant-numeric: tabular-nums;
  font-size: 0.62em;
  line-height: 1.7;
  white-space: nowrap;
}
.tw-qimo.resume-paper .paper-rich ol[data-list="paren-right"] { padding-left: 1.2em; list-style: none; counter-reset: paren-right-item; }
.tw-qimo.resume-paper .paper-rich ol[data-list="paren-right"] > li { position: relative; counter-increment: paren-right-item; }
.tw-qimo.resume-paper .paper-rich ol[data-list="paren-right"] > li::before {
  content: counter(paren-right-item) ")";
  position: absolute;
  right: calc(100% + 0.12em);
  top: 0;
  font-family: var(--mono);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
